<template><div class="min-h-full bg-background p-6"><div class="mx-auto max-w-7xl"><div class="mb-6 flex items-end justify-between"><div><p class="text-xs font-bold uppercase tracking-wider text-primary">Offplan sales</p><h1 class="text-2xl font-black">Bank Financing</h1><p class="text-sm text-slate-500">Track financing records linked to applications.</p></div><button @click="addOpen=true" class="border border-primary bg-primary px-5 py-2.5 font-bold text-white">+ New financing</button></div><div class="mb-4 flex gap-3 border border-slate-200 bg-white p-4"><input v-model="search" class="w-full border p-2.5" placeholder="Search bank, account, status or application"/><button @click="load" class="border px-4">Refresh</button></div><div v-if="error" class="mb-4 border border-red-200 bg-red-50 p-3 text-red-700">{{error}}</div><div class="overflow-x-auto border border-slate-200 bg-white"><table class="min-w-full text-left"><thead class="bg-slate-50"><tr><th class="p-4">Bank</th><th class="p-4">Account</th><th class="p-4">Loan</th><th class="p-4">Rate</th><th class="p-4">Status</th><th class="p-4 text-right">Actions</th></tr></thead><tbody><tr v-for="x in filtered" :key="x.id" class="border-t hover:bg-slate-50"><td class="p-4 font-bold">{{x.bank_name||'—'}}</td><td class="p-4">{{x.loan_account_number||'—'}}</td><td class="p-4">{{x.loan_amount||'—'}}</td><td class="p-4">{{x.interest_rate||'—'}}</td><td class="p-4"><span class="border border-primary/20 bg-primary/10 px-2 py-1 text-xs font-bold text-primary">{{display(x.loan_status)}}</span></td><td class="p-4 text-right"><router-link :to="{name:'OffplanBankFinancing-detail',params:{id:x.id}}" class="border px-3 py-2 text-xs">View</router-link> <button @click="edit(x.id)" class="border border-primary px-3 py-2 text-xs text-primary">Edit</button></td></tr></tbody></table><div v-if="!loading&&!filtered.length" class="p-10 text-center text-slate-500">No financing records found.</div></div></div><AddOffplanBankFinancing :open="addOpen" @close="addOpen=false" @saved="load"/><EditOffplanBankFinancing :open="editOpen" :id="selectedId" @close="editOpen=false" @saved="load"/></div></template><script>import AddOffplanBankFinancing from "./AddOffplanBankFinancing.vue";import EditOffplanBankFinancing from "./EditOffplanBankFinancing.vue";export default{name:"ViewOffplanBankFinancing",components:{AddOffplanBankFinancing,EditOffplanBankFinancing},data(){return{items:[],search:"",loading:false,error:"",addOpen:false,editOpen:false,selectedId:null}},computed:{filtered(){const q=this.search.toLowerCase().trim();return q?this.items.filter(x=>[x.id,x.bank_name,x.loan_account_number,x.loan_amount,x.loan_status,x.application].join(" ").toLowerCase().includes(q)):this.items}},mounted(){this.load()},methods:{async load(){this.loading=true;try{const r=await this.$apiGet("/get_offplan_bank_financings");const d=r?.data?.data||r?.data||r?.financings||r;this.items=Array.isArray(d)?d:(d?.results||[])}catch(e){this.error=e?.message||"Unable to load financing."}finally{this.loading=false}},edit(id){this.selectedId=id;this.editOpen=true},display(v){return String(v||"—").replace(/_/g," ").replace(/\b\w/g,c=>c.toUpperCase())}}};</script>